// ============================================================
// Self-contained AI blog generator (3-node pipeline)
// Fetches queue → picks topic → calls Claude → validates → outputs
// ============================================================

const QUEUE_URL = 'https://raw.githubusercontent.com/mikah33/cortisolplus-web/main/automation/topic-queue.json';
const ANTHROPIC_KEY = 'REPLACE_ANTHROPIC_KEY';
const ANTHROPIC_MODEL = 'claude-sonnet-4-5-20250929';

// --- 1. Load the topic queue ---
const queue = await this.helpers.httpRequest({
  method: 'GET',
  url: QUEUE_URL,
  json: true,
});
if (!Array.isArray(queue) || queue.length === 0) {
  throw new Error('Topic queue is empty or invalid.');
}

// --- 2. Persist which topics have been used ---
const data = $getWorkflowStaticData('global');
if (!Array.isArray(data.usedSlugs)) data.usedSlugs = [];

const topic = queue.find((t) => !data.usedSlugs.includes(t.slug));
if (!topic) {
  throw new Error(`Topic queue exhausted (${queue.length} total, ${data.usedSlugs.length} already used). Add more to automation/topic-queue.json.`);
}

data.usedSlugs.push(topic.slug);

if (!topic.slug || !topic.title || !topic.primaryKeyword) {
  throw new Error('Topic queue entry is malformed: ' + JSON.stringify(topic).substring(0, 300));
}

// --- 3. Build the prompt ---
const today = new Date().toISOString().slice(0, 10);
const targetTool = topic.targetTool || '/tools/cortisol-calculator';
const internalLinks = JSON.stringify(topic.internalLinks || []);

const prompt = `Write a source-linked educational draft for Cortisol+, a stress and HRV wellness app. It does not measure cortisol or diagnose hormone disorders. Do not claim its score is clinically validated. Topic: ${JSON.stringify(topic)}. Return ONLY a JSON object with title, description, tags (array), body (plain Markdown; no HTML, JSX, imports, exports or frontmatter). Use specific primary-source links supporting claims. Do not invent sources or clinical review. Avoid supplement dosing advice, diagnostic quiz claims and promises of hormone reduction. Explain uncertainty. End with a concise educational disclaimer. Use useful internal links naturally. This is a draft for editorial review, not automatic publication.`;

// --- 4. Call Anthropic Claude ---
let claudeBody;
try {
  claudeBody = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.anthropic.com/v1/messages',
    headers: {
      'x-api-key': ANTHROPIC_KEY,
      'anthropic-version': '2023-06-01',
      'content-type': 'application/json'
    },
    body: {
      model: ANTHROPIC_MODEL,
      max_tokens: 4096,
      messages: [{ role: 'user', content: prompt }]
    },
    json: true,
  });
} catch (err) {
  data.usedSlugs = data.usedSlugs.filter((s) => s !== topic.slug);
  throw new Error('Claude API error: ' + (err.message || JSON.stringify(err)).substring(0, 600));
}

const raw = claudeBody.content?.find(b => b.type === 'text')?.text || '';
try {
  const article = JSON.parse(raw.replace(/^```(?:json)?\s*\n/, '').replace(/\n```\s*$/, '').trim());
  if (typeof article.title !== 'string' || typeof article.description !== 'string' || typeof article.body !== 'string') throw new Error('Missing article fields');
  return [{ json: { slug: topic.slug, title: article.title, description: article.description, tags: article.tags, body: article.body } }];
} catch (error) {
  data.usedSlugs = data.usedSlugs.filter(s => s !== topic.slug);
  throw new Error('Draft JSON validation failed: ' + error.message);
}
